function validatePackage(pkg){try{return FadeContentAdapter.validate(pkg)}catch(error){return [error.message||'Invalid lesson package.']}}
function mapPackage(pkg){return FadeContentAdapter.normalize(pkg)}
function showImportErrors(errors){toast(`Lesson data could not load: ${errors[0]}`);console.error('Fade lesson validation:',errors)}
async function loadDemo(){
 clearTimeout(state.landingAgentTimer);
 try{
  if(!window.JSZip)throw new Error('The ZIP reader is still loading. Try again in a moment.');
  const response=await fetch(SPANISH_DEMO_ZIP);
  if(!response.ok)throw new Error(`Spanish demo package could not be loaded (${response.status}).`);
  const archive=await window.JSZip.loadAsync(await response.arrayBuffer());
  const names=['manifest','subtitles','quizzes','vocabulary','culture'];
  const entries=await Promise.all(names.map(async name=>{
   const file=archive.file(`${name}.json`);
   if(!file)throw new Error(`Spanish demo package is missing ${name}.json.`);
   return [name,JSON.parse(await file.async('string'))];
  }));
  const pkg=Object.fromEntries(entries);
  const errors=validatePackage(pkg);
  if(errors.length){showImportErrors(errors);return}
  const content=mapPackage(pkg);
  content.videoId=parseYouTubeId(SPANISH_DEMO_VIDEO_URL);
  content.videoUrl=SPANISH_DEMO_VIDEO_URL;
  await window.FadeWorkflow.createFromPackage(pkg,content,SPANISH_DEMO_VIDEO_URL);
 }catch(e){toast(`Could not load the Spanish demo: ${e.message}`);console.error('Fade Spanish demo:',e)}
}
