function setAnalyzerProgress(config, label, percent){if(!config?.step)return;const safe=Math.max(0,Math.min(100,Number(percent)||0));config.step.textContent=label;config.percent.textContent=`${safe}%`;config.bar.style.width=`${safe}%`}
function resetAnalyzerProgress(config){clearInterval(state.analysisTimer);clearTimeout(state.analysisPoll);if(config?.startLearning)config.startLearning.hidden=true;if(config?.button)config.button.disabled=false;if(config?.step)setAnalyzerProgress(config,'Ready to analyze your video',0)}
function startAnalyzerProgress(config){clearInterval(state.analysisTimer);const startedAt=Date.now();const tick=()=>{const elapsed=Date.now()-startedAt;const estimated=Math.min(95,8+(elapsed/240000)*87);const item=[...LANDING_AGENT_STEPS].reverse().find(step=>estimated>=step.percent)||LANDING_AGENT_STEPS[0];setAnalyzerProgress(config,item.label,Math.floor(estimated))};tick();state.analysisTimer=setInterval(tick,1200)}
function agentUrl(path){if(/^https?:\/\//i.test(path))return path;if(path.startsWith('/api/agent')){if(AGENT_API_BASE.endsWith('/api/agent'))return path;return `${AGENT_API_BASE}${path.slice('/api/agent'.length)}`}return `${AGENT_API_BASE}${path.startsWith('/')?'':'/'}${path}`}
async function fetchAgentJson(url,options){const response=await fetch(agentUrl(url),options);let payload=null;try{payload=await response.json()}catch{}if(!response.ok)throw new Error(payload?.error||payload?.detail||`Agent API returned ${response.status}.`);return payload}
function newCourseRecord(raw,content,videoUrl){const now=new Date().toISOString();return{id:globalThis.crypto?.randomUUID?.()||`course-${Date.now()}`,ownerId:window.FadeAuth?.accountId||'teacher-1',title:content.title||content.videoId||'Untitled lesson',videoId:content.videoId,videoUrl:videoUrl||content.videoUrl||youtubeUrlFromId(content.videoId),sourceLanguage:content.language,translationLanguage:content.translation,originalPackage:FadeCourseEditor.clone(raw),originalContent:FadeCourseEditor.clone(content),teacherContent:null,mode:null,currentTime:0,progress:0,session:null,createdAt:now,updatedAt:now}}
