async function persistCourse(){if(!state.currentCourse||state.activeCourseId!==state.currentCourse.id||!window.FadeCourseStore||!window.FadeCourseAccess?.canOpen(state.currentCourse,window.FadeAuth?.accountId))return;state.currentCourse.updatedAt=new Date().toISOString();state.currentCourse.translation=state.translation;if(state.content&&state.currentCourse.mode==='teacher')state.currentCourse.teacherContent=FadeCourseEditor.clone(state.content);if(state.session)state.currentCourse.session=FadeCourseEditor.clone(state.session);if(state.playerReady&&state.player?.getCurrentTime){state.currentCourse.currentTime=Number(state.player.getCurrentTime())||0;const duration=Number(state.player.getDuration())||Number(state.content?.duration)||0;state.currentCourse.progress=duration?Math.min(100,Math.round(state.currentCourse.currentTime/duration*100)):0}try{await FadeCourseStore.put(state.currentCourse);state.lastCourseSave=Date.now()}catch(error){console.error('Fade course save:',error);toast('Course progress could not be saved locally.')}}
async function finishAnalysis(config,payload,analysisId,accountId){clearInterval(state.analysisTimer);clearTimeout(state.analysisPoll);try{const raw=payload?.package||payload?.result||await fetchAgentJson(payload?.result_url||`/analyses/${encodeURIComponent(analysisId)}/result`);if(state.analysis?.id!==analysisId||window.FadeAuth?.accountId!==accountId)return;const errors=validatePackage(raw);if(errors.length)throw new Error(errors[0]);state.pendingContent=mapPackage(raw);state.pendingContent.videoUrl=state.youtubeUrl||youtubeUrlFromId(state.pendingContent.videoId);await savePendingCourse(raw,state.pendingContent,state.pendingContent.videoUrl);if(state.analysis?.id!==analysisId||window.FadeAuth?.accountId!==accountId)return;updateAnalyzerActionLabels();const teacher=window.FadeAuth?.role==='teacher';setAnalyzerProgress(config,teacher?'Ready for review':'Ready to learn',100);setYoutubeUrlStatus(config,teacher?'Analysis complete. Your course is saved. Start review to check its lesson content.':'Analysis complete. Your course is saved. Start learning when you are ready.','valid');if(config.startLearning)config.startLearning.hidden=false;if(config.button)config.button.disabled=true;state.analysis.status='completed';}catch(error){if(state.analysis?.id!==analysisId||window.FadeAuth?.accountId!==accountId)return;state.analysis.status='failed';setYoutubeUrlStatus(config,`Analysis finished but the lesson could not load: ${error.message}`,'error');if(config.button)config.button.disabled=false}}
async function pollAnalysis(config,analysisId,accountId){if(!state.analysis?.id||state.analysis.id!==analysisId||window.FadeAuth?.accountId!==accountId)return;try{const payload=await fetchAgentJson(`/analyses/${encodeURIComponent(analysisId)}`);if(state.analysis?.id!==analysisId||window.FadeAuth?.accountId!==accountId)return;state.analysis.status=payload.status;if(payload.status==='completed'){await finishAnalysis(config,payload,analysisId,accountId);return}if(payload.status==='failed'){clearInterval(state.analysisTimer);setYoutubeUrlStatus(config,payload.error||'Fade Agent could not analyze this video.','error');if(config.button)config.button.disabled=false;return}const remotePercent=Math.min(95,Number(payload.progress)||0);if(remotePercent>0){const stage=payload.stage||'Fade Agent is analyzing your video';setAnalyzerProgress(config,stage,remotePercent)}state.analysisPoll=setTimeout(()=>pollAnalysis(config,analysisId,accountId),3000);}catch(error){if(state.analysis?.id!==analysisId||window.FadeAuth?.accountId!==accountId)return;clearInterval(state.analysisTimer);setYoutubeUrlStatus(config,`Could not reach Fade Agent: ${error.message}`,'error');if(config.button)config.button.disabled=false}}
async function beginAnalysis(config){
 const raw=config.input?.value.trim()||'',id=parseYouTubeId(raw),source=config.source?.value||'',translation=config.translation?.value||'';
 if(!id){setYoutubeUrlStatus(config,'This field only accepts a YouTube video link. Try youtube.com/watch, youtu.be, or youtube.com/embed.','error');resetAnalyzerProgress(config);toast('Only YouTube video links are supported.');return}
 if(!source||!translation){setYoutubeUrlStatus(config,'Choose the original video language and translation language to continue.','error');resetAnalyzerProgress(config);toast('Choose both languages before starting analysis.');return}
 if(source===translation){setYoutubeUrlStatus(config,'Choose two different languages for the original subtitles and translation.','error');resetAnalyzerProgress(config);toast('The original and translation languages must be different.');return}
 clearTimeout(state.analysisPoll);clearInterval(state.analysisTimer);state.pendingContent=null;state.analysis={id:null,status:'queued',source,translation};state.analysisConfig=config;if(config.startLearning)config.startLearning.hidden=true;if(config.button)config.button.disabled=true;state.youtubeUrl=youtubeUrlFromId(id);saveAnalyzerDraft(config);
 setYoutubeUrlStatus(config,`Your video is queued for Fade Agent analysis · ${id}.`,'valid');startAnalyzerProgress(config);toast('Fade Agent is analyzing your video.');
 const accountId=window.FadeAuth?.accountId;try{const payload=await fetchAgentJson('/analyses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({youtube_url:state.youtubeUrl,source_language:source,target_language:translation})});if(window.FadeAuth?.accountId!==accountId||!state.analysis)return;state.analysis.id=payload.analysis_id||payload.id;if(!state.analysis.id)throw new Error('The Agent API did not return an analysis id.');pollAnalysis(config,state.analysis.id,accountId);}catch(error){if(window.FadeAuth?.accountId!==accountId||!state.analysis)return;clearInterval(state.analysisTimer);state.analysis.status='failed';setYoutubeUrlStatus(config,`Could not start Fade Agent: ${error.message}`,'error');if(config.button)config.button.disabled=false}}
